```python

import os

import shutil


def main():

    directory = input("Enter the path to the directory you want to delete files from: ")

    confirm = input("Are you sure you want to permanently delete all files in this directory? (yes/no): ")


    if confirm.lower() == 'yes':

        try:

            # Get a list of all files in the directory

            files = [f for f in os.listdir(directory) if os.path.isfile(os.path.join(directory, f))]


            for f in files:

                os.remove(os.path.join(directory, f))

                print(f"{f} has been permanently deleted.")

        except Exception as e:

            print("An error occurred while deleting files:", str(e))


    else:

        print("Deletion cancelled by user.")


if __name__ == "__main__":

    main()

```


